<?php
namespace Tests\Feature; use App\Models\Currency; use App\Models\Customer; use App\Models\Employee; use App\Models\Role; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Laravel\Sanctum\Sanctum; use Tests\TestCase;
class EducationalServiceAttributionTest extends TestCase { use RefreshDatabase; protected function setUp():void{parent::setUp();$u=User::factory()->create();$u->roles()->attach(Role::firstOrCreate(['name'=>'super_admin']));Sanctum::actingAs($u,['access']);} public function test_scholarship_service_creates_traceable_bonus_source():void{$customer=Customer::factory()->create();$employee=Employee::factory()->create();$currency=Currency::factory()->create();$this->postJson('/api/educational-services/scholarships',['customer_id'=>$customer->id,'employee_id'=>$employee->id,'currency_id'=>$currency->id,'date'=>'2026-09-17','fee'=>500])->assertCreated();$this->assertDatabaseHas('educational_bonus_sources',['customer_id'=>$customer->id,'employee_id'=>$employee->id,'source_amount'=>500]);}}
